  CONSTRAINT `company_members_status_check` CHECK ((`status` IN ('invited', 'active', 'suspended'))),
  KEY `company_members_company_idx` (`company_id`, `status`),
  KEY `company_members_profile_idx` (`profile_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `company_partnership_requests` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `category` VARCHAR(191) NOT NULL,
  `title` TEXT NOT NULL,
  `details` TEXT NOT NULL,
  `preferred_date` DATE,
  `contact_email` TEXT NOT NULL,
  `status` VARCHAR(191) NOT NULL DEFAULT 'submitted',
  `admin_note` TEXT NOT NULL DEFAULT (''),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `company_partnership_requests_admin_note_check` CHECK ((CHAR_LENGTH(`admin_note`) <= 2000)),
  CONSTRAINT `company_partnership_requests_category_check` CHECK ((`category` IN ('career_day', 'workshop', 'campus_visit', 'internship', 'capstone', 'guest_lecture', 'other'))),
  CONSTRAINT `company_partnership_requests_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `company_partnership_requests_contact_email_check` CHECK (((CHAR_LENGTH(TRIM(`contact_email`)) >= 3) AND (CHAR_LENGTH(TRIM(`contact_email`)) <= 200))),
  CONSTRAINT `company_partnership_requests_created_by_fkey` FOREIGN KEY (`created_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `company_partnership_requests_details_check` CHECK (((CHAR_LENGTH(TRIM(`details`)) >= 20) AND (CHAR_LENGTH(TRIM(`details`)) <= 4000))),
  PRIMARY KEY (`id`),
  CONSTRAINT `company_partnership_requests_status_check` CHECK ((`status` IN ('submitted', 'reviewing', 'approved', 'rejected', 'completed'))),
  CONSTRAINT `company_partnership_requests_title_check` CHECK (((CHAR_LENGTH(TRIM(`title`)) >= 5) AND (CHAR_LENGTH(TRIM(`title`)) <= 160))),
  KEY `company_partnership_requests_company_idx` (`company_id`, `created_at` DESC),
  KEY `company_partnership_requests_status_idx` (`status`, `created_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `connections` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `requester_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `addressee_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` ENUM('pending','accepted','declined','blocked') NOT NULL DEFAULT 'pending',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `responded_at` DATETIME(6),
  CONSTRAINT `connections_addressee_id_fkey` FOREIGN KEY (`addressee_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  PRIMARY KEY (`id`),
  CONSTRAINT `connections_requester_id_fkey` FOREIGN KEY (`requester_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  UNIQUE KEY `connections_pair_idx` ((LEAST(`requester_id`, `addressee_id`)), (GREATEST(`requester_id`, `addressee_id`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `content` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `title` TEXT NOT NULL,
  `subtitle` TEXT NOT NULL DEFAULT (''),
  `status` TEXT NOT NULL DEFAULT ('Qaralama'),
  `meta` TEXT NOT NULL DEFAULT (''),
  `content_key` VARCHAR(191) NOT NULL,
  `body` JSON NOT NULL DEFAULT (CAST('{}' AS JSON)),
  `created_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  UNIQUE KEY `content_content_key_key` (`content_key`),
  CONSTRAINT `content_created_by_fkey` FOREIGN KEY (`created_by`) REFERENCES `auth_users` (`id`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `cv_documents` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` TEXT NOT NULL DEFAULT ('CV'),
  `storage_path` TEXT,
  `source_text` TEXT,
  `template_id` TEXT,
  `language` TEXT NOT NULL DEFAULT ('az'),
  `ats_score` INT,
  `ai_feedback` JSON,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `cv_documents_ats_score_check` CHECK (((`ats_score` >= 0) AND (`ats_score` <= 100))),
  PRIMARY KEY (`id`),
  CONSTRAINT `cv_documents_profile_id_fkey` FOREIGN KEY (`profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `cv_documents_profile_idx` (`profile_id`, `updated_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `education` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `degree_type` VARCHAR(191) NOT NULL,
  `university` TEXT NOT NULL,
  `faculty` TEXT NOT NULL DEFAULT (''),
  `specialty` TEXT NOT NULL,
  `specialization` TEXT NOT NULL DEFAULT (''),
  `group_name` TEXT NOT NULL DEFAULT (''),
  `start_year` INT,
  `graduation_year` INT,
  `is_current` TINYINT(1) NOT NULL DEFAULT 0,
  `verified` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `education_degree_type_check` CHECK ((`degree_type` IN ('bachelor', 'master', 'phd', 'other'))),
  CONSTRAINT `education_graduation_year_check` CHECK (((`graduation_year` >= 1950) AND (`graduation_year` <= 2100))),
  PRIMARY KEY (`id`),
  CONSTRAINT `education_profile_id_fkey` FOREIGN KEY (`profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `education_start_year_check` CHECK (((`start_year` >= 1950) AND (`start_year` <= 2100))),
  KEY `education_profile_idx` (`profile_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `event_registrations` (
  `event_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `event_registrations_event_id_fkey` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE,
  PRIMARY KEY (`event_id`, `profile_id`),
  CONSTRAINT `event_registrations_profile_id_fkey` FOREIGN KEY (`profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `event_regs_profile_idx` (`profile_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `events` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `title` TEXT NOT NULL,
  `kind` TEXT DEFAULT (''),
  `starts_at` DATETIME(6) NOT NULL,
  `place` TEXT DEFAULT (''),
  `seats` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `description` TEXT,
  `organizers` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `image_url` TEXT,
  CONSTRAINT `events_image_url_https` CHECK (((`image_url` IS NULL) OR REGEXP_LIKE(`image_url`, '^https://', 'c'))),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `faculties` (
  `id` VARCHAR(191) NOT NULL,
  `name` VARCHAR(191) NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  UNIQUE KEY `faculties_name_key` (`name`),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `follows` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `follower_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `followed_profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `followed_company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `follows_followed_company_id_fkey` FOREIGN KEY (`followed_company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `follows_followed_profile_id_fkey` FOREIGN KEY (`followed_profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `follows_follower_id_fkey` FOREIGN KEY (`follower_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  PRIMARY KEY (`id`),
  KEY `follows_company_idx` (`followed_company_id`),
  KEY `follows_profile_idx` (`followed_profile_id`),
  UNIQUE KEY `follows_unique_company_idx` (`follower_id`, `followed_company_id`),
  UNIQUE KEY `follows_unique_profile_idx` (`follower_id`, `followed_profile_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `interview_requests` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `application_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `student_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(191) NOT NULL DEFAULT 'pending',
  `message` TEXT NOT NULL DEFAULT (''),
  `reply_note` TEXT NOT NULL DEFAULT (''),
  `scheduled_slot_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `interview_requests_application_id_fkey` FOREIGN KEY (`application_id`) REFERENCES `applications` (`id`) ON DELETE CASCADE,
  UNIQUE KEY `interview_requests_application_id_key` (`application_id`),
  CONSTRAINT `interview_requests_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `interview_requests_message_check` CHECK ((CHAR_LENGTH(`message`) <= 1000)),
  PRIMARY KEY (`id`),
  CONSTRAINT `interview_requests_reply_note_check` CHECK ((CHAR_LENGTH(`reply_note`) <= 1000)),
  CONSTRAINT `interview_requests_scheduled_slot_id_fkey` FOREIGN KEY (`scheduled_slot_id`) REFERENCES `company_interview_slots` (`id`) ON DELETE SET NULL,
  CONSTRAINT `interview_requests_status_check` CHECK ((`status` IN ('pending', 'accepted', 'declined', 'scheduled', 'cancelled'))),
  CONSTRAINT `interview_requests_student_id_fkey` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `interview_requests_company_status_idx` (`company_id`, `status`, `created_at` DESC),
  KEY `interview_requests_student_status_idx` (`student_id`, `status`, `created_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `interview_sessions` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `target_role` TEXT NOT NULL,
  `interview_type` TEXT NOT NULL,
  `major` TEXT,
  `questions` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `answers` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `score` INT,
  `deterministic_result` JSON,
  `ai_feedback` JSON,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `completed_at` DATETIME(6),
  CONSTRAINT `interview_sessions_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `interview_sessions_job_id_fkey` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`) ON DELETE SET NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `interview_sessions_profile_id_fkey` FOREIGN KEY (`profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `interview_sessions_score_check` CHECK (((`score` >= 0) AND (`score` <= 100))),
  KEY `interview_sessions_profile_idx` (`profile_id`, `created_at` DESC),
  KEY `interviews_company_idx` (`company_id`),
  KEY `interviews_job_idx` (`job_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `invites` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `student_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` TEXT NOT NULL DEFAULT ('Göndərilib'),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `invites_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  UNIQUE KEY `invites_company_id_student_id_job_id_key` (`company_id`, `student_id`, `job_id`),
  CONSTRAINT `invites_job_id_fkey` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`) ON DELETE CASCADE,
  PRIMARY KEY (`id`),
  CONSTRAINT `invites_student_id_fkey` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `invites_job_idx` (`job_id`),
  KEY `invites_student_idx` (`student_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `jobs` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` TEXT NOT NULL,
  `type` ENUM('is','tecrube','graduate','konullu') NOT NULL,
  `mode` TEXT NOT NULL DEFAULT ('Əyani'),
  `location` TEXT NOT NULL DEFAULT ('Bakı'),
  `deadline` DATE NOT NULL,
  `duration` TEXT DEFAULT (''),
  `pay` TEXT DEFAULT (''),
  `faculty_ids` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `major_ids` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `skills` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `min_course` INT DEFAULT 1,
  `min_gpa` DECIMAL(5,2) DEFAULT 0,
  `summary` TEXT DEFAULT (''),
  `duties` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `requirements` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `status` ENUM('draft','pending','approved','rejected','closed','pending_approval','changes_requested','published','expired','archived') NOT NULL DEFAULT 'pending',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `approved_at` DATETIME(6),
  `approved_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `department` TEXT,
  `salary_min` DECIMAL(12,2),
  `salary_max` DECIMAL(12,2),
  `currency` TEXT NOT NULL DEFAULT ('AZN'),
  `featured_until` DATETIME(6),
  `preferred_skills` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `experience_level` TEXT NOT NULL DEFAULT ('Təcrübə tələb olunmur'),
  `salary_visible` TINYINT(1) NOT NULL DEFAULT 0,
  `positions` INT NOT NULL DEFAULT 1,
  `application_method` TEXT NOT NULL DEFAULT ('platform'),
  `application_url` TEXT,
  `rejection_reason` TEXT,
  `changes_requested` TEXT,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `jobs_approved_by_fkey` FOREIGN KEY (`approved_by`) REFERENCES `profiles` (`id`) ON DELETE SET NULL,
  CONSTRAINT `jobs_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  PRIMARY KEY (`id`),
  CONSTRAINT `jobs_positions_check` CHECK ((`positions` > 0)),
  KEY `jobs_company_idx` (`company_id`),
  KEY `jobs_company_status_idx` (`company_id`, `status`, `created_at` DESC),
  KEY `jobs_deadline_idx` (`deadline`),
  KEY `jobs_status_idx` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `majors` (
  `id` VARCHAR(191) NOT NULL,
  `faculty_id` VARCHAR(191) NOT NULL,
  `name` VARCHAR(191) NOT NULL,
  `field` TEXT NOT NULL,
  CONSTRAINT `majors_faculty_id_fkey` FOREIGN KEY (`faculty_id`) REFERENCES `faculties` (`id`) ON DELETE CASCADE,
  UNIQUE KEY `majors_faculty_id_name_key` (`faculty_id`, `name`),
  PRIMARY KEY (`id`),
  KEY `majors_faculty_idx` (`faculty_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `mentor_requests` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `student_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `category` VARCHAR(191) NOT NULL,
  `topic` TEXT NOT NULL,
  `details` TEXT NOT NULL,
  `format` VARCHAR(191) NOT NULL DEFAULT 'either',
  `preferred_time` TEXT NOT NULL DEFAULT (''),
  `status` VARCHAR(191) NOT NULL DEFAULT 'pending',
  `mentor_name` TEXT NOT NULL DEFAULT (''),
  `admin_note` TEXT NOT NULL DEFAULT (''),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `mentor_requests_admin_note_check` CHECK ((CHAR_LENGTH(`admin_note`) <= 1200)),
  CONSTRAINT `mentor_requests_category_check` CHECK ((`category` IN ('karyera', 'cv', 'müsahibə', 'texniki', 'startap', 'magistr', 'şəbəkələşmə'))),
  CONSTRAINT `mentor_requests_details_check` CHECK (((CHAR_LENGTH(TRIM(`details`)) >= 15) AND (CHAR_LENGTH(TRIM(`details`)) <= 1800))),
  CONSTRAINT `mentor_requests_format_check` CHECK ((`format` IN ('online', 'in_person', 'either'))),
  CONSTRAINT `mentor_requests_mentor_name_check` CHECK ((CHAR_LENGTH(`mentor_name`) <= 120)),
  PRIMARY KEY (`id`),
  CONSTRAINT `mentor_requests_preferred_time_check` CHECK ((CHAR_LENGTH(`preferred_time`) <= 180)),
  CONSTRAINT `mentor_requests_status_check` CHECK ((`status` IN ('pending', 'in_review', 'matched', 'completed', 'cancelled'))),
  CONSTRAINT `mentor_requests_student_id_fkey` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `mentor_requests_topic_check` CHECK (((CHAR_LENGTH(TRIM(`topic`)) >= 5) AND (CHAR_LENGTH(TRIM(`topic`)) <= 140))),
  KEY `mentor_requests_admin_status_idx` (`status`, `created_at` DESC),
  KEY `mentor_requests_student_created_idx` (`student_id`, `created_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `messages` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `sender_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `recipient_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `body` TEXT NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `read_at` DATETIME(6),
  CONSTRAINT `messages_body_check` CHECK (((CHAR_LENGTH(TRIM(`body`)) >= 1) AND (CHAR_LENGTH(TRIM(`body`)) <= 4000))),
  PRIMARY KEY (`id`),
  CONSTRAINT `messages_recipient_id_fkey` FOREIGN KEY (`recipient_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `messages_sender_id_fkey` FOREIGN KEY (`sender_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `messages_inbox_idx` (`recipient_id`, `created_at` DESC),
  KEY `messages_thread_idx` (`sender_id`, `recipient_id`, `created_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `moderation_allow` (
  `word` VARCHAR(191) NOT NULL,
  `script` TEXT NOT NULL DEFAULT ('latin'),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`word`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `moderation_logs` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `report_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `target_type` VARCHAR(191) NOT NULL,
  `target_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `action` VARCHAR(191) NOT NULL,
  `reason` TEXT NOT NULL DEFAULT (''),
  `actor_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `moderation_logs_action_check` CHECK ((`action` IN ('approve', 'hide', 'delete', 'warn', 'suspend', 'restore'))),
  CONSTRAINT `moderation_logs_actor_id_fkey` FOREIGN KEY (`actor_id`) REFERENCES `profiles` (`id`) ON DELETE SET NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `moderation_logs_report_id_fkey` FOREIGN KEY (`report_id`) REFERENCES `reports` (`id`) ON DELETE SET NULL,
  KEY `moderation_logs_actor_idx` (`actor_id`),
  KEY `moderation_logs_report_idx` (`report_id`),
  KEY `moderation_logs_target_idx` (`target_type`, `target_id`, `created_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `moderation_terms` (
  `term` VARCHAR(191) NOT NULL,
  `match` VARCHAR(191) NOT NULL DEFAULT 'stem',
  `lang` TEXT NOT NULL DEFAULT ('az'),
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `script` VARCHAR(191) NOT NULL,
  `tier` VARCHAR(191) NOT NULL DEFAULT 'A',
  `source` TEXT NOT NULL DEFAULT ('admin'),
  CONSTRAINT `moderation_terms_match_check` CHECK ((`match` IN ('stem', 'word', 'infix'))),
  PRIMARY KEY (`term`),
  CONSTRAINT `moderation_terms_script_check` CHECK ((`script` IN ('latin', 'cyrillic', 'arabic'))),
  CONSTRAINT `moderation_terms_tier_check` CHECK ((`tier` IN ('A', 'B'))),
  KEY `moderation_terms_infix_idx` (`script`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `notifications` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `kind` TEXT NOT NULL,
  `title` TEXT NOT NULL,
  `body` TEXT NOT NULL DEFAULT (''),
  `link` TEXT,
  `read_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  CONSTRAINT `notifications_profile_id_fkey` FOREIGN KEY (`profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `notifications_profile_idx` (`profile_id`, `read_at`, `created_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `payments` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subscription_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `provider` TEXT NOT NULL DEFAULT ('manual'),
  `provider_reference` TEXT,
  `amount` DECIMAL(10,2) NOT NULL,
  `currency` TEXT NOT NULL DEFAULT ('AZN'),
  `status` VARCHAR(191) NOT NULL DEFAULT 'pending',
  `paid_at` DATETIME(6),
  `metadata` JSON NOT NULL DEFAULT (CAST('{}' AS JSON)),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `plan_id` VARCHAR(191),
  `months` INT NOT NULL DEFAULT 1,
  `invoice_number` VARCHAR(191),
  `due_at` DATETIME(6),
  CONSTRAINT `payments_amount_check` CHECK ((`amount` >= (0))),
  CONSTRAINT `payments_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `payments_months_check` CHECK (((`months` >= 1) AND (`months` <= 12))),
  PRIMARY KEY (`id`),
  CONSTRAINT `payments_plan_id_fkey` FOREIGN KEY (`plan_id`) REFERENCES `plans` (`id`),
  CONSTRAINT `payments_status_check` CHECK ((`status` IN ('pending', 'paid', 'failed', 'refunded', 'cancelled'))),
  CONSTRAINT `payments_subscription_id_fkey` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions` (`id`) ON DELETE SET NULL,
  KEY `payments_company_idx` (`company_id`, `created_at` DESC),
  KEY `payments_company_status_idx` (`company_id`, `status`),
  UNIQUE KEY `payments_invoice_number_key` (`invoice_number`),
  KEY `payments_subscription_idx` (`subscription_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `plan_features` (
  `plan_id` VARCHAR(191) NOT NULL,
  `feature_key` VARCHAR(191) NOT NULL,
  `label` TEXT NOT NULL,
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
  `limit_value` INT,
  `config` JSON NOT NULL DEFAULT (CAST('{}' AS JSON)),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `plan_features_limit_value_check` CHECK (((`limit_value` IS NULL) OR (`limit_value` >= 0))),
  PRIMARY KEY (`plan_id`, `feature_key`),
  CONSTRAINT `plan_features_plan_id_fkey` FOREIGN KEY (`plan_id`) REFERENCES `plans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `plans` (
  `id` VARCHAR(191) NOT NULL,
  `name` TEXT NOT NULL,
  `monthly_price` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `currency` TEXT NOT NULL DEFAULT ('USD'),
  `active_job_limit` INT,
  `featured_job_limit` INT NOT NULL DEFAULT 0,
  `candidate_search` TINYINT(1) NOT NULL DEFAULT 0,
  `ai_ranking` TINYINT(1) NOT NULL DEFAULT 0,
  `advanced_analytics` TINYINT(1) NOT NULL DEFAULT 0,
  `priority_support` TINYINT(1) NOT NULL DEFAULT 0,
  `active` TINYINT(1) NOT NULL DEFAULT 1,
  `sort_order` INT NOT NULL DEFAULT 0,
  `description` TEXT NOT NULL DEFAULT (''),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `post_comments` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `post_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `author_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `body` TEXT NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `moderation_status` VARCHAR(191) NOT NULL DEFAULT 'pending',
  `moderation_reason` TEXT,
  `moderated_at` DATETIME(6),
  `moderation_requested_at` DATETIME(6),
  `moderation_attempts` INT NOT NULL DEFAULT 0,
  CONSTRAINT `post_comments_author_id_fkey` FOREIGN KEY (`author_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `post_comments_body_check` CHECK (((CHAR_LENGTH(TRIM(`body`)) >= 1) AND (CHAR_LENGTH(TRIM(`body`)) <= 1000))),
  CONSTRAINT `post_comments_moderation_status_check` CHECK ((`moderation_status` IN ('pending', 'visible', 'hidden'))),
  PRIMARY KEY (`id`),
  CONSTRAINT `post_comments_post_id_fkey` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  KEY `post_comments_author_idx` (`author_id`),
  KEY `post_comments_moderation_pending_idx` (`moderation_requested_at`),
  KEY `post_comments_post_idx` (`post_id`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `post_likes` (
  `post_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`post_id`, `profile_id`),
  CONSTRAINT `post_likes_post_id_fkey` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `post_likes_profile_id_fkey` FOREIGN KEY (`profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `post_likes_profile_idx` (`profile_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `post_media` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `post_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `media_type` VARCHAR(191) NOT NULL,
  `storage_path` TEXT,
  `public_url` TEXT,
  `title` TEXT NOT NULL DEFAULT (''),
  `sort_order` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `post_media_check` CHECK (((`storage_path` IS NOT NULL) OR (`public_url` IS NOT NULL))),
  CONSTRAINT `post_media_media_type_check` CHECK ((`media_type` IN ('image', 'pdf', 'document', 'link'))),
  PRIMARY KEY (`id`),
  CONSTRAINT `post_media_post_id_fkey` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  KEY `post_media_post_idx` (`post_id`, `sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `post_saves` (
  `post_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`post_id`, `profile_id`),
  CONSTRAINT `post_saves_post_id_fkey` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `post_saves_profile_id_fkey` FOREIGN KEY (`profile_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `post_saves_profile_idx` (`profile_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `posts` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `author_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `body` TEXT NOT NULL,
  `link_url` TEXT,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `edited_at` DATETIME(6),
  `kind` VARCHAR(191) NOT NULL DEFAULT 'general',
  `tags` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `attachment_url` TEXT,
  `moderation_status` VARCHAR(191) NOT NULL DEFAULT 'pending',
  `moderation_reason` TEXT,
  `moderated_at` DATETIME(6),
  `moderation_requested_at` DATETIME(6),
  `moderation_attempts` INT NOT NULL DEFAULT 0,
  CONSTRAINT `posts_author_id_fkey` FOREIGN KEY (`author_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `posts_body_check` CHECK (((CHAR_LENGTH(TRIM(`body`)) >= 1) AND (CHAR_LENGTH(TRIM(`body`)) <= 4000))),
  PRIMARY KEY (`id`),
  KEY `posts_author_idx` (`author_id`),
  KEY `posts_created_idx` (`created_at` DESC),
  KEY `posts_feed_idx` (`moderation_status`, `created_at` DESC),
  KEY `posts_kind_idx` (`kind`, `created_at` DESC),
  KEY `posts_moderation_pending_idx` (`moderation_requested_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `profiles` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `role` ENUM('student','graduate','company','admin') NOT NULL DEFAULT 'student',
  `status` ENUM('pending','active','rejected') NOT NULL DEFAULT 'active',
  `email` TEXT NOT NULL,
  `full_name` TEXT NOT NULL DEFAULT (''),
  `phone` TEXT DEFAULT (''),
  `city` TEXT DEFAULT ('Bakı, Azərbaycan'),
  `faculty_id` VARCHAR(191),
  `major_id` VARCHAR(191),
  `course` INT,
  `gpa` DECIMAL(5,2),
  `start_year` INT,
  `skills` JSON NOT NULL DEFAULT (JSON_ARRAY()),
  `languages` TEXT DEFAULT (''),
  `certificates` TEXT DEFAULT (''),
  `summary` TEXT DEFAULT (''),
  `linkedin` TEXT DEFAULT (''),
  `github` TEXT DEFAULT (''),
  `portfolio` TEXT DEFAULT (''),
  `cv_url` TEXT,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `personal_email` TEXT,
  `account_status` TEXT NOT NULL DEFAULT ('student'),
  `alumni_verified` TINYINT(1) NOT NULL DEFAULT 0,
  `profile_visibility` TEXT NOT NULL DEFAULT ('platform'),
  `admin_role` VARCHAR(191),
  `university` TEXT NOT NULL DEFAULT ('Azərbaycan Dövlət Neft və Sənaye Universiteti'),
  `group_name` TEXT NOT NULL DEFAULT (''),
  `avatar_url` TEXT,
  `avatar_path` VARCHAR(191),
  `avatar_pending_path` TEXT,
  `avatar_requested_at` DATETIME(6),
  `avatar_attempts` INT NOT NULL DEFAULT 0,
  `avatar_reason` TEXT,
  `avatar_moderated_at` DATETIME(6),
  `avatar_submit_day` DATE,
  `avatar_submit_count` INT NOT NULL DEFAULT 0,
  `experience` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  `projects` JSON NOT NULL DEFAULT (CAST('[]' AS JSON)),
  CONSTRAINT `profiles_admin_role_check` CHECK (((`admin_role` IS NULL) OR (`admin_role` IN ('super_admin', 'manager', 'editor', 'reviewer')))),
  CONSTRAINT `profiles_course_check` CHECK (((`course` >= 1) AND (`course` <= 6))),
  CONSTRAINT `profiles_experience_shape` CHECK (((JSON_TYPE(`experience`) = 'ARRAY') AND (JSON_LENGTH(`experience`) <= 30) AND (LENGTH(CAST(`experience` AS CHAR)) <= 30000))),
  CONSTRAINT `profiles_faculty_id_fkey` FOREIGN KEY (`faculty_id`) REFERENCES `faculties` (`id`) ON DELETE SET NULL,
  CONSTRAINT `profiles_gpa_check` CHECK (((`gpa` >= (0)) AND (`gpa` <= (100)))),
  CONSTRAINT `profiles_id_fkey` FOREIGN KEY (`id`) REFERENCES `auth_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `profiles_major_id_fkey` FOREIGN KEY (`major_id`) REFERENCES `majors` (`id`) ON DELETE SET NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `profiles_projects_shape` CHECK (((JSON_TYPE(`projects`) = 'ARRAY') AND (JSON_LENGTH(`projects`) <= 30) AND (LENGTH(CAST(`projects` AS CHAR)) <= 30000))),
  KEY `profiles_avatar_path_idx` (`avatar_path`),
  KEY `profiles_avatar_pending_idx` (`avatar_requested_at`),
  KEY `profiles_faculty_idx` (`faculty_id`),
  KEY `profiles_major_idx` (`major_id`),
  KEY `profiles_role_idx` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `reports` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `reporter_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_type` VARCHAR(191) NOT NULL,
  `target_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` TEXT NOT NULL,
  `details` TEXT NOT NULL DEFAULT (''),
  `status` VARCHAR(191) NOT NULL DEFAULT 'open',
  `reviewed_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `reviewed_at` DATETIME(6),
  PRIMARY KEY (`id`),
  CONSTRAINT `reports_reporter_id_fkey` FOREIGN KEY (`reporter_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reports_reviewed_by_fkey` FOREIGN KEY (`reviewed_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `reports_status_check` CHECK ((`status` IN ('open', 'reviewing', 'resolved', 'dismissed'))),
  CONSTRAINT `reports_target_type_check` CHECK ((`target_type` IN ('post', 'comment', 'profile', 'company', 'job'))),
  KEY `reports_reporter_idx` (`reporter_id`),
  KEY `reports_reviewer_idx` (`reviewed_by`),
  KEY `reports_status_idx` (`status`, `created_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `saved_jobs` (
  `student_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  CONSTRAINT `saved_jobs_job_id_fkey` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`) ON DELETE CASCADE,
  PRIMARY KEY (`student_id`, `job_id`),
  CONSTRAINT `saved_jobs_student_id_fkey` FOREIGN KEY (`student_id`) REFERENCES `profiles` (`id`) ON DELETE CASCADE,
  KEY `saved_jobs_job_idx` (`job_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `site_content` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `content_key` VARCHAR(191) NOT NULL,
  `title` TEXT NOT NULL,
  `summary` TEXT NOT NULL DEFAULT (''),
  `body` TEXT NOT NULL DEFAULT (''),
  `status` VARCHAR(191) NOT NULL DEFAULT 'Qaralama',
  `updated_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  UNIQUE KEY `site_content_content_key_key` (`content_key`),
  PRIMARY KEY (`id`),
  CONSTRAINT `site_content_status_check` CHECK ((`status` IN ('Aktiv', 'Qaralama', 'Bitib'))),
  CONSTRAINT `site_content_updated_by_fkey` FOREIGN KEY (`updated_by`) REFERENCES `auth_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `subscription_usage` (
  `subscription_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `feature_key` VARCHAR(191) NOT NULL,
  `period_start` DATE NOT NULL,
  `period_end` DATE NOT NULL,
  `used_count` INT NOT NULL DEFAULT 0,
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`subscription_id`, `feature_key`, `period_start`),
  CONSTRAINT `subscription_usage_subscription_id_fkey` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `subscription_usage_used_count_check` CHECK ((`used_count` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE TABLE `subscriptions` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT (UUID()),
  `company_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `plan_id` VARCHAR(191) NOT NULL,
  `status` VARCHAR(191) NOT NULL DEFAULT 'active',
  `starts_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `ends_at` DATETIME(6),
  `requested_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `approved_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
  `requested_plan_id` VARCHAR(191),
  `reminder_sent_at` DATETIME(6),
  CONSTRAINT `subscriptions_approved_by_fkey` FOREIGN KEY (`approved_by`) REFERENCES `profiles` (`id`),
  CONSTRAINT `subscriptions_company_id_fkey` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  UNIQUE KEY `subscriptions_company_id_key` (`company_id`),
  PRIMARY KEY (`id`),
  CONSTRAINT `subscriptions_plan_id_fkey` FOREIGN KEY (`plan_id`) REFERENCES `plans` (`id`),
  CONSTRAINT `subscriptions_requested_plan_id_fkey` FOREIGN KEY (`requested_plan_id`) REFERENCES `plans` (`id`),
  CONSTRAINT `subscriptions_status_check` CHECK ((`status` IN ('pending', 'active', 'past_due', 'cancelled'))),
  KEY `subscriptions_approver_idx` (`approved_by`),
  KEY `subscriptions_plan_idx` (`plan_id`),
  KEY `subscriptions_status_idx` (`status`, `plan_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_ci;

CREATE OR REPLACE VIEW `company_subscriptions` AS
SELECT s.id,
    s.company_id,
    s.plan_id,
    s.status,
    s.starts_at,
    s.ends_at,
    s.requested_at,
    s.approved_by,
    p.name AS plan_name,
    p.monthly_price,
    p.currency,
    s.requested_plan_id
   FROM (subscriptions s
     JOIN plans p ON ((p.id = s.plan_id)));

SET FOREIGN_KEY_CHECKS = 1;
